#!/bin/sh
# Generates sample.zip, the ZIP archive for the archive tests.
#
# Needs only python3. The result only differs between machines if their zlib deflates
# differently, so it is checked in rather than generated by the tests:
#
#     sh tests/fixtures/generate-zip.sh
#
# Contents (checked by tests/archive.rs). Times are DOS local times, 2 s resolution.
#
#     docs/                     explicit folder, 2024-01-02 03:04:06
#     docs/readme.txt           "hello zip\n" x 3, deflated
#     docs/sub/deep.txt         "deep\n", stored; docs/sub/ has no entry of its own
#     top.txt                   "top\n", deflated, 2024-02-03 04:05:06
#     größe.txt                 "unicode\n", UTF-8 flag set
#     café.txt                  "cp437\n", name in CP437 (0x82), no UTF-8 flag
#     naïve.txt                 "utf8\n", name in UTF-8 but without the flag (Info-ZIP style)
#     empty/                    explicit empty folder
#     zero.txt                  empty file
#     bzip2.txt, lzma.txt       "bzip2\n" x 100 and "lzma\n" x 100, with those methods
#     big.bin                   300000 bytes, byte i = (i * 7) % 251, deflated
#     big-stored.bin            300000 bytes, byte i = (i * 11) % 241, stored
#     link                      symlink entry to "docs/readme.txt"
#     win\dir\file.txt          "win\n", Windows-style separators
#     docs/secret.txt           flagged as encrypted (ZipCrypto), the data is not decryptable
#     zstd.txt                  method 93 (Zstandard), which the app doesn't decode (not real zstd data)
#     ../evil.txt, /abs.txt, docs/../up.txt     hostile names, must never show up
set -eu

out=$(cd "$(dirname "$0")" && pwd)/sample.zip
python3 -I - "$out" <<'EOF'
import struct
import sys
import zipfile

out = sys.argv[1]
STORED, DEFLATED = zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED


def info(name, mode, method, time=(2024, 2, 3, 4, 5, 6)):
    zi = zipfile.ZipInfo(name, date_time=time)
    zi.create_system = 3  # Unix: the mode in external_attr counts
    zi.compress_type = method
    zi.external_attr = mode << 16
    return zi


with zipfile.ZipFile(out, "w") as z:
    z.writestr(info("docs/", 0o40755, STORED, (2024, 1, 2, 3, 4, 6)), b"")
    z.writestr(info("docs/readme.txt", 0o100644, DEFLATED), b"hello zip\n" * 3)
    z.writestr(info("docs/sub/deep.txt", 0o100644, STORED), b"deep\n")
    z.writestr(info("top.txt", 0o100644, DEFLATED), b"top\n")
    z.writestr(info("größe.txt", 0o100644, DEFLATED), b"unicode\n")
    z.writestr(info("caf_.txt", 0o100644, DEFLATED), b"cp437\n")  # patched below
    z.writestr(info("naXXve.txt", 0o100644, DEFLATED), b"utf8\n")  # patched below
    z.writestr(info("empty/", 0o40755, STORED), b"")
    z.writestr(info("zero.txt", 0o100644, STORED), b"")
    z.writestr(info("bzip2.txt", 0o100644, zipfile.ZIP_BZIP2), b"bzip2\n" * 100)
    z.writestr(info("lzma.txt", 0o100644, zipfile.ZIP_LZMA), b"lzma\n" * 100)
    z.writestr(info("big.bin", 0o100644, DEFLATED), bytes(i * 7 % 251 for i in range(300000)))
    z.writestr(info("big-stored.bin", 0o100644, STORED), bytes(i * 11 % 241 for i in range(300000)))
    z.writestr(info("link", 0o120777, STORED), b"docs/readme.txt")
    z.writestr(info("win\\dir\\file.txt", 0o100644, STORED), b"win\n")
    z.writestr(info("docs/secret.txt", 0o100644, STORED), b"\0" * 12 + b"enc")
    z.writestr(info("zstd.txt", 0o100644, STORED), b"not zstd\n")
    z.writestr(info("../evil.txt", 0o100644, STORED), b"evil\n")
    z.writestr(info("/abs.txt", 0o100644, STORED), b"abs\n")
    z.writestr(info("docs/../up.txt", 0o100644, STORED), b"up\n")
    central = z.start_dir

data = bytearray(open(out, "rb").read())
# Same-length replacements: python only writes ASCII or flagged UTF-8 names.
for old, new in ((b"caf_.txt", b"caf\x82.txt"), (b"naXXve.txt", "naïve.txt".encode())):
    assert data.count(old) == 2, old  # local header and central directory
    data[:] = data.replace(old, new)
# docs/secret.txt: set the "encrypted" bit in both of its headers. zstd.txt: change the method.
pos = central
while data[pos:pos + 4] == b"PK\x01\x02":
    name_len, extra_len, comment_len = struct.unpack_from("<HHH", data, pos + 28)
    entry = data[pos + 46:pos + 46 + name_len]
    (local,) = struct.unpack_from("<I", data, pos + 42)
    if entry == b"docs/secret.txt":
        for at in (pos + 8, local + 6):
            data[at] |= 1
    if entry == b"zstd.txt":
        for at in (pos + 10, local + 8):
            struct.pack_into("<H", data, at, 93)
    pos += 46 + name_len + extra_len + comment_len
open(out, "wb").write(data)
EOF
ls -l "$out"
